settings.custom_css:
/* DWARKA PEETH THEME VARIABLES */
:root {
    --bg-color: #F4F8FB; 
    --dwarka-blue: #0A3D62; /* Deep Ocean Blue */
    --dwarka-light: #1F618D;
    --gold-accent: #D4AF37;
    --text-dark: #2C3E50;
    --text-light: #5D6D7E;
    --box-bg: #FFFFFF;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
    background-color: var(--bg-color); 
    color: var(--text-dark); 
    font-family: 'Lato', sans-serif; 
    line-height: 1.8; 
    overflow-x: hidden;
}

/* Background Pattern */
.bg-pattern {
    position: fixed; top: 0; left: 0; width: 100%; height: 100%; 
    background-image: radial-gradient(var(--dwarka-light) 0.5px, transparent 0.5px); 
    background-size: 30px 30px; opacity: 0.1; z-index: -1;
}

/* LANGUAGE SWITCHER */
body[data-lang="en"] .hi { display: none !important; }
body[data-lang="hi"] .en { display: none !important; }

.lang-switcher {
    position: absolute; top: 30px; right: 5%; z-index: 1000;
    display: flex; gap: 5px; background: #fff; padding: 5px;
    border-radius: 30px; box-shadow: 0 4px 10px rgba(0,0,0,0.1);
    border: 2px solid var(--gold-accent);
}
.lang-btn {
    background: transparent; border: none; padding: 6px 15px;
    border-radius: 20px; font-family: 'Lato', sans-serif; font-weight: 700;
    color: var(--dwarka-blue); cursor: pointer; transition: 0.3s;
}
.lang-btn.active {
    background: var(--dwarka-blue); color: #fff;
}

/* HERO SECTION */
.profile-hero {
    display: flex; flex-wrap: wrap; align-items: center; justify-content: center; 
    padding: 100px 5% 50px; gap: 50px; max-width: 1400px; margin: 0 auto;
}

.hero-text-col { flex: 1; min-width: 350px; }
.peeth-tag {
    display: inline-block; color: var(--dwarka-light); font-weight: 700; 
    letter-spacing: 2px; text-transform: uppercase; font-size: 0.9rem; 
    margin-bottom: 10px; border-bottom: 2px solid var(--dwarka-light); padding-bottom: 5px;
}
.main-title {
    font-family: 'Cinzel', serif; font-size: clamp(2.2rem, 4vw, 3.8rem); 
    color: var(--dwarka-blue); line-height: 1.2; margin-bottom: 15px;
}
.sub-title { font-size: 1.2rem; color: var(--text-light); font-weight: 400; margin-bottom: 30px; }

/* Info Grid */
.info-grid {
    display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); 
    gap: 15px; margin-top: 30px;
}
.info-item {
    background: var(--box-bg); border-left: 4px solid var(--gold-accent); 
    padding: 15px; box-shadow: 0 5px 15px rgba(10, 61, 98, 0.08); border-radius: 5px;
}
.info-label {
    font-size: 0.75rem; text-transform: uppercase; color: var(--text-light); 
    letter-spacing: 1px; display: block;
}
.info-val {
    font-family: 'Cinzel', serif; font-size: 1.1rem; color: var(--dwarka-blue); font-weight: 700;
}

/* IMAGE COL */
.hero-image-col { flex: 1; min-width: 300px; max-width: 450px; text-align: center; }
.portrait-frame {
    padding: 15px; background: var(--box-bg); border-radius: 15px; 
    box-shadow: 0 15px 40px rgba(10, 61, 98, 0.15); border: 2px solid var(--gold-accent);
}
.main-img { width: 100%; height: auto; border-radius: 10px; display: block; }
.img-caption {
    text-align: center; background: linear-gradient(to right, var(--dwarka-blue), var(--dwarka-light)); 
    color: #fff; padding: 10px; font-family: 'Cinzel', serif; font-size: 0.95rem; margin-top: 15px; border-radius: 5px;
}

/* CONTENT BODY */
.content-container { max-width: 900px; margin: 0 auto 80px; padding: 0 25px; }

.chapter-heading {
    font-family: 'Cinzel', serif; font-size: 2rem; color: var(--dwarka-blue); 
    margin: 50px 0 20px; display: flex; align-items: center; gap: 15px;
}

.part-heading {
    font-family: 'Alegreya', serif; font-size: 1.5rem; color: #fff; 
    background: var(--dwarka-blue); padding: 10px 15px; border-radius: 5px; 
    margin: 30px 0 15px; text-align: center; font-weight: bold;
}

/* GURU PARAMPARA LIST */
.guru-row {
    display: flex; gap: 20px; align-items: flex-start; padding: 15px 0; 
    border-bottom: 1px dashed rgba(212, 175, 55, 0.3);
}
.guru-row:last-child { border-bottom: none; }

.guru-icon {
    flex-shrink: 0; width: 45px; height: 45px; border: 2px solid var(--gold-accent); 
    border-radius: 50%; display: flex; align-items: center; justify-content: center; 
    font-weight: 700; color: var(--dwarka-blue); background: #FFF8F0; 
    font-family: 'Cinzel', serif; font-size: 1.1em;
}

.guru-details { flex-grow: 1; }
.guru-name-title { font-size: 1.15em; color: var(--dwarka-blue); font-weight: 700; display: block; }
.guru-period { display: block; font-size: 0.85em; color: #888; margin-top: 2px; }
.guru-desc { font-size: 0.95em; color: #555; margin-top: 5px; }

/* Highlight Current Acharya */
.guru-row.current {
    background: linear-gradient(to right, rgba(212, 175, 55, 0.1), transparent); 
    border-radius: 10px; padding: 15px; border: 1px solid var(--gold-accent);
}
.guru-row.current .guru-icon {
    background: var(--dwarka-light); color: #fff; border-color: var(--dwarka-light);
}

/* SPECIAL INFO TABLE */
.highlight-box {
    background: #FFFDF8; border: 2px solid var(--gold-accent); 
    padding: 30px; border-radius: 10px; box-shadow: 0 5px 20px rgba(0,0,0,0.05);
}
.info-table { width: 100%; border-collapse: collapse; margin-top: 15px; }
.info-table th, .info-table td {
    padding: 12px 15px; border-bottom: 1px solid rgba(212, 175, 55, 0.3); text-align: left;
}
.info-table th { width: 30%; color: var(--dwarka-blue); font-family: 'Cinzel', serif; font-weight: 700; }
.info-table td { color: var(--text-dark); font-family: 'Alegreya', serif; font-size: 1.1rem; }
.info-table tr:last-child th, .info-table tr:last-child td { border-bottom: none; }

/* MEDIA QUERIES */
@media (max-width: 768px) {
    .profile-hero { flex-direction: column-reverse; text-align: center; padding-top: 90px; }
    .hero-image-col { width: 100%; }
    .lang-switcher { top: 20px; right: 50%; transform: translateX(50%); }
    .info-table th, .info-table td { display: block; width: 100%; }
    .info-table th { padding-bottom: 0; }
    .info-table td { padding-top: 5px; }
}
